export * as List from './list.tsx';
export type {
  ItemOwnProps as ListItemOwnProps,
  ItemProps as ListItemProps,
  LeadingOwnProps as ListLeadingOwnProps,
  LeadingProps as ListLeadingProps,
  RootOwnProps as ListRootOwnProps,
  RootProps as ListRootProps,
} from './list.tsx';

@layer hj.components {
  /*
   * Customise: --hj-list-row-height (56) · --hj-list-padding (row inline padding) ·
   * --hj-list-leading-size (40) · --hj-list-gap (12)
   */
  .hj-list {
    margin: 0;
    padding: 0;
    list-style: none;
    font-family: var(--hj-font-sans);
    color: var(--hj-fg);
  }

  .hj-list-item {
    --_pad: var(--hj-list-padding, 0px);
    --_gap: var(--hj-list-gap, 12px);
    --_lead: 0px;
    position: relative;
    display: block;
  }
  .hj-list-item:has(.hj-list-leading) {
    --_lead: calc(var(--hj-list-leading-size, 40px) + var(--_gap));
  }
  /* One interactive row puts every row on the same inset, so mixed lists stay aligned. */
  .hj-list-item[data-interactive],
  .hj-list:has(> [data-interactive]) > .hj-list-item {
    --_pad: var(--hj-list-padding, 12px);
  }
  /* Hairline between rows, starting where the text starts. */
  .hj-list[data-divided] > .hj-list-item + .hj-list-item::before {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    left: calc(var(--_pad) + var(--_lead));
    height: 1px;
    background: var(--hj-line);
    pointer-events: none;
  }

  .hj-list-row {
    display: flex;
    align-items: center;
    gap: var(--_gap);
    width: 100%;
    min-height: var(--hj-list-row-height, 56px);
    padding: 8px var(--_pad);
    border: 0;
    border-radius: var(--hj-radius-sm);
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: start;
    text-decoration: none;
  }
  .hj-list-item[data-interactive] > .hj-list-row {
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-list-item[data-interactive]:not([data-disabled]) > .hj-list-row:hover {
    background: color-mix(in srgb, var(--hj-fg) 4%, transparent);
  }
  /* Rows answer a press with opacity, not scale — a list must not wobble. */
  .hj-list-item[data-interactive]:not([data-disabled]) > .hj-list-row:active {
    opacity: var(--hj-press-opacity);
    transition-duration: 70ms;
  }
  .hj-list-item[data-interactive] > .hj-list-row:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: -2px;
  }
  .hj-list-item[data-disabled] > .hj-list-row {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .hj-list-leading {
    display: grid;
    place-items: center;
    flex: none;
    min-width: 0;
    color: var(--hj-fg-dim);
    font-size: 20px;
    line-height: 0;
  }
  .hj-list-leading[data-variant='art'],
  .hj-list-leading[data-variant='icon'],
  .hj-list-leading[data-variant='avatar'] {
    width: var(--hj-list-leading-size, 40px);
    height: var(--hj-list-leading-size, 40px);
    overflow: hidden;
  }
  .hj-list-leading[data-variant='art'] {
    border-radius: var(--hj-radius-xs);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }
  .hj-list-leading[data-variant='avatar'] {
    border-radius: var(--hj-radius-pill);
    background: var(--hj-accent-soft);
    color: var(--hj-accent);
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
  }
  .hj-list-leading[data-variant='art'] > :is(img, svg, video),
  .hj-list-leading[data-variant='avatar'] > :is(img, svg) {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  .hj-list-leading[data-variant='icon'] {
    --_t: var(--hj-fg);
    border-radius: var(--hj-radius-xs);
    background: color-mix(in srgb, var(--_t) 10%, transparent);
    color: var(--_t);
  }
  .hj-list-leading[data-tone='accent'] {
    --_t: var(--hj-accent);
  }
  .hj-list-leading[data-tone='success'] {
    --_t: var(--hj-success);
  }
  .hj-list-leading[data-tone='warning'] {
    --_t: var(--hj-warning);
  }
  .hj-list-leading[data-tone='danger'] {
    --_t: var(--hj-danger);
  }

  .hj-list-content {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
  }
  .hj-list-title {
    overflow: hidden;
    font: var(--hj-type-body);
    letter-spacing: var(--hj-tracking-body);
    white-space: nowrap;
    text-overflow: ellipsis;
    color: var(--hj-fg);
    transition: color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-list-item[data-selected] .hj-list-title {
    color: var(--hj-accent);
  }
  .hj-list-description {
    display: flex;
    align-items: center;
    gap: 5px;
    overflow: hidden;
    font: var(--hj-type-sub);
    letter-spacing: var(--hj-tracking-sub);
    white-space: nowrap;
    text-overflow: ellipsis;
    color: var(--hj-fg-mute);
  }
  .hj-list-description > .hj-icon {
    font-size: 14px;
  }

  .hj-list-trailing {
    display: flex;
    flex: none;
    align-items: center;
    gap: 8px;
    margin-inline-start: auto;
    color: var(--hj-fg-mute);
  }
  .hj-list-value {
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
    text-align: end;
    color: var(--hj-fg-dim);
  }
  .hj-list-chevron {
    display: inline-flex;
    font-size: 18px;
    line-height: 0;
    color: var(--hj-fg-mute);
  }
  .hj-list-chevron > svg {
    width: 1em;
    height: 1em;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

/*
 * No context anywhere: every part is a plain element styled by CSS, so a virtualised list of
 * thousands of rows pays nothing per row beyond its own elements.
 */

export const Content: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'List.Content',
  'hj-list-content',
);
export const Title: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'List.Title',
  'hj-list-title',
);
export const Description: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'List.Description',
  'hj-list-description',
);
export const Trailing: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'List.Trailing',
  'hj-list-trailing',
);
/** A number in the trailing slot: tabular mono, right-aligned. */
export const Value: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'List.Value',
  'hj-list-value',
);

export interface RootOwnProps {
  /** Hairlines between rows, inset to the text column. @default true */
  divided?: boolean;
}
export type RootProps = RootOwnProps & ElementPartProps<'ul'>;

/** A list of rows. Renders `<ul>`; use `render={<ol />}` for an ordered list. */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const { divided = true, render, className, ...rest } = withDefaults(config, 'List.Root', props);
  return useRender({
    render,
    defaultTagName: 'ul',
    props: {
      ...rest,
      'data-divided': flag(divided),
      className: cls(config, 'List.Root', 'hj-list', className) as string | undefined,
    },
  });
}

export interface ItemOwnProps {
  /** The row the user is on or has chosen: title in accent, aria-current set. */
  selected?: boolean;
  disabled?: boolean;
}
export type ItemProps = ItemOwnProps &
  Omit<React.ComponentProps<'li'>, 'className'> & {
    className?: string;
    /**
     * Replace the row element inside the `<li>` — e.g. `render={<a href="/album/42" />}` or
     * `render={<button type="button" />}` — to make the whole row interactive. The `<li>`
     * stays, so the list keeps valid structure.
     */
    render?: useRender.RenderProp;
  };

/** One 56px row: Leading · Content (Title, Description) · Trailing. */
export function Item(props: ItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    selected = false,
    disabled = false,
    render,
    className,
    children,
    ...rest
  } = withDefaults(config, 'List.Item', props);
  const interactive = render !== undefined;
  const row = useRender({
    render,
    defaultTagName: 'div',
    props: {
      className: config.unstyled ? undefined : 'hj-list-row',
      'aria-current': interactive && selected ? true : undefined,
      'aria-disabled': interactive && disabled ? true : undefined,
      tabIndex: interactive && disabled ? -1 : undefined,
      children,
    },
  });
  return (
    <li
      {...rest}
      data-interactive={flag(interactive)}
      data-selected={flag(selected)}
      data-disabled={flag(disabled)}
      className={cls(config, 'List.Item', 'hj-list-item', className) as string | undefined}
    >
      {row}
    </li>
  );
}

export interface LeadingOwnProps {
  /** art = 40px rounded image · icon = glyph in a tinted square · avatar = 40px circle · plain. */
  variant?: 'plain' | 'art' | 'icon' | 'avatar';
  /** Tint for `icon`. */
  tone?: 'neutral' | 'accent' | 'success' | 'warning' | 'danger';
}
export type LeadingProps = LeadingOwnProps & ElementPartProps<'div'>;

/** The left slot: artwork, an icon in a tint, an avatar. */
export function Leading(props: LeadingProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    variant = 'plain',
    tone = 'neutral',
    render,
    className,
    ...rest
  } = withDefaults(config, 'List.Leading', props);
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      'data-variant': variant,
      'data-tone': variant === 'icon' ? tone : undefined,
      className: cls(config, 'List.Leading', 'hj-list-leading', className) as string | undefined,
    },
  });
}

/** The trailing ›, for rows that open something. Decorative. */
export function Chevron(props: Omit<React.ComponentProps<'span'>, 'children'>): React.ReactElement {
  const config = useHanjiConfig();
  const { className, ...rest } = props;
  return (
    <span
      aria-hidden="true"
      {...rest}
      className={cls(config, 'List.Chevron', 'hj-list-chevron', className) as string | undefined}
    >
      {config.icons.chevronRight}
    </span>
  );
}
